import { chromium } from 'playwright';import fs from 'fs';const b=await chromium.launch({headless:true});const out={errors:[],mobile:[],desktop:[]};async function check(w,h,label){const p=await b.newPage({viewport:{width:w,height:h}});p.on('pageerror',e=>out.errors.push(label+': '+e.message));await p.goto('http://127.0.0.1:4173/',{waitUntil:'domcontentloaded'});await p.evaluate(()=>{localStorage.setItem('lemma-entered','true');uxHome()});let sw=await p.evaluate(()=>Math.max(document.body.scrollWidth,document.documentElement.scrollWidth));out[label].push(['home',sw,await p.locator('.mission').count()]);await p.screenshot({path:`artifacts/${label}-home.png`,fullPage:true});await p.evaluate(()=>uxPath());sw=await p.evaluate(()=>Math.max(document.body.scrollWidth,document.documentElement.scrollWidth));out[label].push(['path',sw,await p.locator('.node').count()]);await p.screenshot({path:`artifacts/${label}-path.png`,fullPage:true});await p.evaluate(()=>{PROG.hello={done:true};PROG.abc1={done:true};PROG.abc2={done:true};PROG.abc3={done:true};PROG.rev1={done:true};uxTopic('family')});sw=await p.evaluate(()=>Math.max(document.body.scrollWidth,document.documentElement.scrollWidth));out[label].push(['topic',sw,await p.locator('.step').count()]);await p.screenshot({path:`artifacts/${label}-topic.png`,fullPage:true});await p.evaluate(()=>uxOpen('family','family_l1'));await p.waitForTimeout(100);sw=await p.evaluate(()=>Math.max(document.body.scrollWidth,document.documentElement.scrollWidth));out[label].push(['lesson',sw,await p.locator('#uxbar').count()]);await p.screenshot({path:`artifacts/${label}-lesson.png`,fullPage:true});await p.evaluate(()=>{SAVED={topic:'family',lessonId:'family_l1',stage:'practice',step:1,score:0,mistakes:0};saveAll()});await p.reload({waitUntil:'domcontentloaded'});out[label].push(['saved',await p.evaluate(()=>!!SAVED&&SAVED.lessonId==='family_l1')]);await p.close()}fs.mkdirSync('artifacts',{recursive:true});await check(390,844,'mobile');await check(1366,768,'desktop');const p=await b.newPage({viewport:{width:390,height:844}});await p.goto('http://127.0.0.1:4173/',{waitUntil:'domcontentloaded'});out.review=await p.evaluate(()=>({rev1:[LESSONS.rev1.theory.length,LESSONS.rev1.tasks.length,!!LESSONS.rev1_l1],rev2:[LESSONS.rev2.theory.length,LESSONS.rev2.tasks.length,!!LESSONS.rev2_l1],topics:TOPICS[2].map(x=>x.id),next:nextTopicId('rev2')}));out.types=await p.evaluate(()=>['choice','listen','match','gap','letters','order','dnd','tf','speak'].map(t=>[t,!!LESSONS&&Object.values(LESSONS).some(L=>(L.tasks||[]).some(x=>x.t===t))]));await p.close();await b.close();fs.writeFileSync('artifacts/results.json',JSON.stringify(out,null,2));if(out.errors.length)process.exit(2);if(out.mobile.some(x=>typeof x[1]==='number'&&x[1]>390))process.exit(3);if(out.review.rev1[0]!==3||out.review.rev1[1]!==14||out.review.rev1[2]||out.review.rev2[0]!==3||out.review.rev2[1]!==14||out.review.rev2[2])process.exit(4);